  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { const v = 104 + (r() - 0.5) * 38 + (r() < 0.015 ? 55 : 0); const i = (y * n + x) * 4; img.data[i] = v; img.data[i + 1] = v * 0.99; img.data[i + 2] = v * 0.96; img.data[i + 3] = 255; }
