  cvidPrefetch('suez'); szSetup(0); GAME.state = 'play'; $('#app').classList.add('play'); for (const m of ['#mBrief', '#mPause', '#mEnd']) $(m).hidden = true;
  initAudio(); lockPointer(); toast('24 באוקטובר 1973 · 10:40', 'העיר סואץ, שעות לפני הפסקת האש');
