  if (!R.joined) { const [wx, wz] = CW(R.cx, lz); m.visible = true; m.position.set(wx, R.yS + (t > 9.5 ? Math.sin(t * 7) * 0.02 : 0), wz); m.rotation.set(0, 0, 0); if (dt > 0 && t > 9.5 && Math.random() < dt * 5) fxDust(V3(wx + rand(-3, 3), R.yS - 0.6, wz - 2.6)); }
