  fmMan((s) => s.grp === 'ES' && s.lx > 106 && s.lx < 205, 'f2', { wakeR: 9 }, 9, kind);
  fmMan((s) => s.grp === 'PS' && s.pl.j === 0 && s.lx > 106, 'f2', { wakeR: 9 }, 6, kind);
  fmMan((s) => s.grp === 'PS' && s.pl.j === 1 && s.lx > 120, 'f2', { wakeR: 9 }, 4, kind);
