  if (FM.stage === S_JCT && Math.random() < 0.3) { const v = fmNearestTank([e.pos.x, e.pos.z]); if (v && Math.hypot(v.g.position.x - e.pos.x, v.g.position.z - e.pos.z) < 120) return v.g.position.clone().add(V3(rand(-2, 2), 1.4, rand(-2, 2))); }
