  if (FM.stage === S_YARD && (FM.ph !== 'yard' || (FM.bar && FM.bar.on && FM.bar.phase !== 'calm') || FM.slip.st !== 'ready' || FM.hitAnim || (FM.bar && FM.bar.on && FM.bar.calm - FM.bar.t < 4))) return false;
